import { dgnUnpackTicket, dgnColorMatches } from './dgn-traits.js';

/** Per-lane points for one settled card: one for an equal symbol, plus color
 * points (both wild 2, one wild 1, else equal colors 1). The player's hero is
 * the wild lane of their ticket. Point allocations that disagree with the
 * recorded score are withheld until the board completes. */
export function projectPopRow(row) {
  const player = dgnUnpackTicket(row.playerTraits);
  const house = row.houseTraits == null ? null : dgnUnpackTicket(row.houseTraits);
  const score = Math.max(0, Number(row.score) || 0);
  const heroLane = player.findIndex(lane => lane.wild);
  const quadrants = player.map((p, q) => {
    const h = house?.[q] ?? null;
    const symbolMatch = Boolean(h && p.sym === h.sym);
    const colorMatch = Boolean(h && dgnColorMatches(p, h));
    const points = h
      ? (symbolMatch ? 1 : 0) + (colorMatch ? (p.wild && h.wild ? 2 : 1) : 0)
      : null;
    return { player: p, house: h, points, symbolMatch, colorMatch, hero: heroLane === q };
  });
  const exact = Boolean(house) && quadrants.reduce((sum, quadrant) => sum + quadrant.points, 0) === score;
  if (!exact) for (const quadrant of quadrants) quadrant.points = null;
  return { score, hero: heroLane < 0 ? null : heroLane, exact, quadrants };
}

/** Reveal state lives independently of DOM, timers, and animation completion. */
export function createPopState(rows) {
  const boards = rows.map(row => projectPopRow(row));
  const masks = boards.map(() => 0);
  const snapshot = () => ({
    masks: masks.slice(),
    complete: masks.every(mask => mask === 15),
    completed: masks.filter(mask => mask === 15).length,
    score: boards.reduce((total, board, i) => total + (board.exact
      ? board.quadrants.reduce((sum, q, j) => sum + ((masks[i] & (1 << j)) ? q.points : 0), 0)
      : masks[i] === 15 ? board.score : 0), 0),
  });
  return {
    boards, snapshot,
    reveal(index, mask = 15) {
      if (!Number.isInteger(index) || index < 0 || index >= boards.length) return [];
      const added = (Number(mask) & 15) & ~masks[index];
      masks[index] |= added;
      return boards[index].quadrants.flatMap((quadrant, q) => (
        added & (1 << q) ? [{ ...quadrant, board: index, quadrant: q }] : []
      ));
    },
  };
}
